import re
import json
from collections import Counter
def task_func(json_str, top_n=10):
    try:
        data = json.loads(json_str)
    except Exception:
        return {}
    if not isinstance(data, dict):
        return {}
    url_pattern = re.compile(r'https?://(?:[A-Za-z0-9\-._~%]+(?:\.[A-Za-z0-9\-._~%]+)+|localhost|\d{1,3}(?:\.\d{1,3}){3})(?::\d+)?(?:/[^\s"\'<>\)\]\}]+)?', re.IGNORECASE)
    urls = []
    def traverse(obj):
        if isinstance(obj, dict):
            for v in obj.values():
                traverse(v)
        elif isinstance(obj, (list, tuple)):
            for item in obj:
                traverse(item)
        elif isinstance(obj, str):
            urls.extend(url_pattern.findall(obj))
    traverse(data)
    counts = Counter(urls)
    if top_n is None:
        return dict(counts)
    if top_n <= 0:
        return {}
    return dict(counts.most_common(top_n))
