import json
import pandas as pd
import numpy as np
from collections import defaultdict
def task_func(input_file="data.json"):
    try:
        with open(input_file, "r") as f:
            data = json.load(f)
    except Exception:
        return pd.DataFrame(columns=["mean", "median"])
    if not isinstance(data, list):
        data = []
    all_keys = set()
    values = defaultdict(list)
    for item in data:
        if isinstance(item, dict):
            all_keys.update(item.keys())
            for k, v in item.items():
                if isinstance(v, bool):
                    continue
                if isinstance(v, (int, float)) and np.isfinite(v):
                    values[k].append(float(v))
    stats = {}
    for k in all_keys:
        vals = values.get(k, [])
        if len(vals) == 0:
            stats[k] = {"mean": np.nan, "median": np.nan}
        else:
            stats[k] = {"mean": float(np.mean(vals)), "median": float(np.median(vals))}
    if stats:
        df = pd.DataFrame.from_dict(stats, orient="index")
    else:
        df = pd.DataFrame(columns=["mean", "median"])
    df = df.reindex(columns=["mean", "median"])
    df = df.sort_index()
    return df
