import json
import re
import pandas as pd
def task_func(json_str):
    if not isinstance(json_str, str) or not json_str.strip():
        return pd.DataFrame()
    try:
        data = json.loads(json_str)
    except Exception:
        return pd.DataFrame()
    if not isinstance(data, dict):
        return pd.DataFrame()
    num_pattern = re.compile(r'^\s*([+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?)\s*$')
    def str_to_number(s):
        m = num_pattern.match(s)
        if m:
            try:
                return float(m.group(1))
            except Exception:
                return None
        return None
    def normalize_value(v):
        if isinstance(v, bool):
            return v
        if isinstance(v, (int, float)):
            return float(v) * 2.0
        if isinstance(v, str):
            n = str_to_number(v)
            return n * 2.0 if n is not None else v
        if isinstance(v, (list, tuple)):
            out = []
            for x in v:
                if isinstance(x, bool):
                    out.append(x)
                elif isinstance(x, (int, float)):
                    out.append(float(x) * 2.0)
                elif isinstance(x, str):
                    n = str_to_number(x)
                    out.append(n * 2.0 if n is not None else x)
                else:
                    out.append(x)
            return out
        return v
    normalized = {k: normalize_value(v) for k, v in data.items()}
    list_lengths = [len(v) for v in normalized.values() if isinstance(v, (list, tuple))]
    if list_lengths and len(set(list_lengths)) == 1:
        n = list_lengths[0]
        aligned = {}
        for k, v in normalized.items():
            if isinstance(v, (list, tuple)):
                if len(v) != n:
                    aligned = None
                    break
                aligned[k] = list(v)
            else:
                aligned[k] = [v] * n
        if aligned is not None:
            try:
                return pd.DataFrame(aligned)
            except Exception:
                return pd.DataFrame()
    try:
        return pd.DataFrame([normalized])
    except Exception:
        return pd.DataFrame()
