import json
import re
from collections import Counter
# Constants
REPLACE_NONE = "None"
def task_func(json_str):
    try:
        data = json.loads(json_str)
    except json.JSONDecodeError:
        return {"data": None, "value_counts": Counter()}
    email_pattern = re.compile(r'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}\b')
    def cleanse(x):
        if isinstance(x, dict):
            res = {}
            for k, v in x.items():
                if v is None:
                    continue
                res[k] = cleanse(v)
            return res
        if isinstance(x, list):
            return [cleanse(i) for i in x if i is not None]
        if isinstance(x, str):
            return email_pattern.sub(REPLACE_NONE, x)
        return x
    processed = cleanse(data)
    counts = Counter()
    def collect(x):
        if isinstance(x, dict):
            for v in x.values():
                collect(v)
        elif isinstance(x, list):
            for i in x:
                collect(i)
        else:
            counts[x] += 1
    collect(processed)
    return {"data": processed, "value_counts": counts}
