import json
import pandas as pd
from sklearn.preprocessing import MinMaxScaler
import matplotlib.pyplot as plt
def task_func(json_data: str, data_key: str):
    data = json.loads(json_data)

    def resolve_key_path(obj, path):
        parts = [p for p in path.split('.') if p]
        cur = obj
        for seg in parts:
            if isinstance(cur, dict):
                if seg in cur:
                    cur = cur[seg]
                else:
                    raise KeyError('Key path is not found')
            elif isinstance(cur, list):
                if seg.isdigit():
                    idx = int(seg)
                    if 0 <= idx < len(cur):
                        cur = cur[idx]
                    else:
                        raise KeyError('Key path is not found')
                else:
                    raise KeyError('Key path is not found')
            else:
                raise KeyError('Key path is not found')
        return cur

    target = resolve_key_path(data, data_key)

    def extract_numeric(obj):
        if isinstance(obj, (list, tuple)):
            iterable = obj
        elif isinstance(obj, dict):
            iterable = obj.values()
        else:
            iterable = [obj]
        out = []
        for v in iterable:
            if isinstance(v, bool):
                continue
            try:
                fv = float(v)
            except Exception:
                continue
            if pd.isna(fv):
                continue
            out.append(fv)
        return out

    nums = extract_numeric(target)
    original_series = pd.Series(nums, dtype='float64')

    if original_series.empty:
        return original_series, None, None

    scaler = MinMaxScaler()
    normalized_values = scaler.fit_transform(original_series.values.reshape(-1, 1)).ravel()
    normalized_series = pd.Series(normalized_values, index=original_series.index, dtype='float64')

    fig, ax = plt.subplots()
    ax.plot(original_series.index, original_series.values, label='Original Data')
    ax.plot(normalized_series.index, normalized_series.values, label='Normalized Data')
    ax.set_title('Comparison of Original and Normalized Data')
    ax.set_xlabel('Index')
    ax.set_ylabel('Value')
    ax.legend()

    return original_series, normalized_series, ax
